int process_ticket_reply(struct ceph_auth_client *ac, struct ceph_crypto_key *secret,
                         void *buf, void *end) {
    int version;
    int num_tickets;
    int ret;
    void *p = buf;

    if (p + sizeof(version) > end)
        return -EINVAL;

    version = *(int *)p;
    p += sizeof(version);

    if (version != 1) {
        // Only version 1 is supported
        return -EINVAL;
    }

    if (p + sizeof(num_tickets) > end)
        return -EINVAL;

    num_tickets = *(int *)p;
    p += sizeof(num_tickets);

    for (int i = 0; i < num_tickets; i++) {
        ret = process_one_ticket(ac, secret, &p, end);
        if (ret < 0)
            return ret;
    }

    return 0;
}

int process_ticket_reply(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void *buf, void *end)
{
    int version;
    int num_tickets;
    int i;
    int ret;

    if ((void *)&version >= end) {
        return -EINVAL;
    }
    decode_version(&version, &buf, end);

    if (version != 1) {
        return -EINVAL;
    }

    if ((void *)&num_tickets >= end) {
        return -EINVAL;
    }
    decode_num(&num_tickets, &buf, end);

    for (i = 0; i < num_tickets; i++) {
        ret = process_one_ticket(ac, secret, buf, end);
        if (ret < 0) {
            return ret;
        }
    }

    return 0;
}

