int ceph_process_ticket_reply(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void *buf, void *end)
{
    int ret = 0;
    int num_tickets;
    int version;

    if ((ret = ceph_decode_version(&version, buf, end)) < 0)
        return ret;

    if (version != 1) {
        return -EINVAL;
    }

    if ((ret = ceph_decode_num(&num_tickets, buf, end)) < 0)
        return ret;

    for (int i = 0; i < num_tickets; i++) {
        ret = process_one_ticket(ac, secret, buf, end);
        if (ret < 0)
            return ret;
    }

    return 0;
}

int process_ticket_reply(struct ceph_auth_client *ac, struct ceph_crypto_key *secret,
                         void *buf, void *end)
{
    int ret;
    int num_tickets;
    int version;

    if (buf >= end)
        return -EINVAL;

    version = ceph_decode_32(&buf, end);
    if (version != 1) {
        pr_err("Unsupported ticket reply version %d\n", version);
        return -EINVAL;
    }

    num_tickets = ceph_decode_32(&buf, end);
    if (num_tickets < 0)
        return num_tickets;

    for (int i = 0; i < num_tickets; i++) {
        ret = process_one_ticket(ac, secret, buf, end);
        if (ret < 0)
            return ret;
        buf = (void *)((uintptr_t)buf + ret);
    }

    return 0;
}
